package cn.pi.overtime;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
public final class UpdateManager {
 final Activity activity;volatile boolean busy=false,cancelled=false,dead=false;AlertDialog progress;TextView label;
 public UpdateManager(Activity a){activity=a;}
 int current()throws Exception{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionCode;}
 void ui(Runnable r){activity.runOnUiThread(()->{if(!dead&&!activity.isFinishing()&&!activity.isDestroyed())r.run();});}
 void toast(String s){Toast.makeText(activity,s,Toast.LENGTH_LONG).show();}
 static HttpURLConnection open(String url)throws Exception{for(int n=0;n<6;n++){URL u=new URL(url);String host=u.getHost();if(!"https".equals(u.getProtocol())||!Arrays.asList("raw.githubusercontent.com","github.com","release-assets.githubusercontent.com","objects.githubusercontent.com").contains(host))throw new IOException("更新地址不受支持");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","OvertimeStats-Android");c.setRequestProperty("Cache-Control","no-cache");int code=c.getResponseCode();if(code>=300&&code<400){String target=c.getHeaderField("Location");c.disconnect();if(target==null)throw new IOException("下载跳转无效");url=new URL(u,target).toString();continue;}if(code!=200){c.disconnect();throw new IOException("服务器返回HTTP "+code);}return c;}throw new IOException("下载跳转过多");}
 static String metadata()throws Exception{Exception last=null;for(String address:new String[]{"https://raw.githubusercontent.com/lyz10-26/OvertimeStats/main/latest.json","https://github.com/lyz10-26/OvertimeStats/raw/refs/heads/main/latest.json"}){HttpURLConnection c=null;try{c=open(address);try(InputStream input=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>65536)throw new IOException("更新说明过大");out.write(b,0,n);}return out.toString("UTF-8");}}catch(Exception e){last=e;}finally{if(c!=null)c.disconnect();}}throw last;}
 public void check(){if(busy){toast("正在检查或下载更新");return;}busy=true;cancelled=false;toast("正在检查更新…");new Thread(()->{try{UpdateInfo info=new UpdateInfo(metadata());int installed=current();if(info.code==installed){busy=false;ui(()->toast("已是最新版"));return;}if(info.code<installed){busy=false;ui(()->toast("更新服务版本低于当前安装版本，暂未发布可用更新"));return;}ui(()->download(info));}catch(Exception e){busy=false;ui(()->toast("检查更新失败，请稍后重试"));}}).start();}
 void download(UpdateInfo info){LinearLayout box=new LinearLayout(activity);box.setOrientation(1);int pad=(int)(24*activity.getResources().getDisplayMetrics().density);box.setPadding(pad,pad/2,pad,pad/2);label=new TextView(activity);label.setText("正在下载 "+info.version+"…\n"+info.notes);label.setTextSize(14);box.addView(label);ProgressBar bar=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);bar.setIndeterminate(true);box.addView(bar);progress=new AlertDialog.Builder(activity).setTitle("发现新版本 "+info.version).setView(box).setNegativeButton("取消",(v,w)->cancelled=true).create();progress.setOnCancelListener(v->cancelled=true);progress.show();new Thread(()->{File part=new File(activity.getCacheDir(),"update.part"),apk=new File(activity.getCacheDir(),"update.apk");HttpURLConnection c=null;try{c=open(info.url);int size=c.getContentLength();if(size>50*1024*1024)throw new IOException("安装包大小异常");MessageDigest digest=MessageDigest.getInstance("SHA-256");int total=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(part)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(cancelled||dead)throw new InterruptedIOException();total+=n;if(total>50*1024*1024)throw new IOException("安装包过大");out.write(b,0,n);digest.update(b,0,n);}}if(cancelled||dead)throw new InterruptedIOException();StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format(Locale.ROOT,"%02x",b&255));if(!hex.toString().equalsIgnoreCase(info.sha))throw new IOException("安装包校验失败");verify(part,info.code);if(apk.exists()&&!apk.delete())throw new IOException("无法替换安装包");if(!part.renameTo(apk))throw new IOException("无法保存安装包");busy=false;ui(()->{if(progress!=null)progress.dismiss();install();});}catch(Exception e){part.delete();busy=false;ui(()->{if(progress!=null)progress.dismiss();if(!cancelled)toast("更新下载失败："+(e instanceof IOException?e.getMessage():"安装包签名或版本校验失败"));});}finally{if(c!=null)c.disconnect();}}).start();}
 void verify(File file,int expected)throws Exception{PackageManager pm=activity.getPackageManager();PackageInfo archive=pm.getPackageArchiveInfo(file.getAbsolutePath(),PackageManager.GET_SIGNATURES),installed=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNATURES);if(archive==null||!activity.getPackageName().equals(archive.packageName)||archive.versionCode!=expected||archive.versionCode<=installed.versionCode||archive.signatures==null||installed.signatures==null||!new HashSet<android.content.pm.Signature>(Arrays.asList(archive.signatures)).equals(new HashSet<android.content.pm.Signature>(Arrays.asList(installed.signatures))))throw new SecurityException("签名或版本不匹配");}
 void install(){try{if(!activity.getPackageManager().canRequestPackageInstalls()){activity.getSharedPreferences("attendance",0).edit().putBoolean("pendingUpdateInstall",true).apply();toast("请允许安装此来源的应用，返回后继续安装");activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));return;}File apk=new File(activity.getCacheDir(),"update.apk");PackageInfo info=activity.getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(),0);if(info==null)throw new IOException();verify(apk,info.versionCode);Uri uri=Uri.parse("content://"+activity.getPackageName()+".updates/update.apk");Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(i);}catch(Exception e){toast("无法启动安装，请重新检查更新");}}
 public void resume(){android.content.SharedPreferences p=activity.getSharedPreferences("attendance",0);if(p.getBoolean("pendingUpdateInstall",false)){p.edit().remove("pendingUpdateInstall").apply();if(activity.getPackageManager().canRequestPackageInstalls())install();}}
 public void destroy(){dead=true;cancelled=true;if(progress!=null)progress.dismiss();}
}
